function enterLab(){if(!surface||!labInterior||interiorActive)return;interiorKind='lab';if(activeCrew!==2){setFeedback('The field laboratory is for the Scientist. Switch to Player 2 · Scientist to enter.',false);return;}setViewMode(false);if(driving&&rover){const pilot=crewActor();if(pilot){pilot.position.set(rover.position.x+2,height(rover.position.x+2,rover.position.z+1),rover.position.z+1);pilot.visible=true;}driving=false;}heading=heading2=velocity=velocity2=0;interiorRestore=root.children.map(o=>[o,o.visible]);crewPoseRestore=[astronaut,astronaut2].filter(Boolean).map(a=>({actor:a,position:a.position.clone(),rotation:a.rotation.y,visible:a.visible}));interiorRestore.forEach(([o])=>o.visible=false);labInterior.visible=true;if(astronaut)astronaut.visible=false;if(astronaut2){astronaut2.visible=true;astronaut2.position.set(.35,0,1.1);astronaut2.rotation.y=0;}interiorActive=true;$('#station-nav').hidden=true;$('#inspect').hidden=true;$('#mission-panel').classList.add('interior');$('#exit-lab').textContent='Exit lab';$('#exit-lab').hidden=false;$('#hint').textContent='FIELD LAB · Walk freely: Player 1 W/A/S/D · Player 2 arrow keys · In first-person, drag to look · Click instruments';controls.minDistance=1.25;controls.maxDistance=4.25;controls.minPolarAngle=.12;controls.maxPolarAngle=1.42;camera.position.set(activeCrew===1?-1.15:1.15,2.25,3.55);controls.target.set(activeCrew===1?-1.15:1.15,1.45,-.8);controls.update();}
function exitLab(){if(!interiorActive)return;interiorRestore.forEach(([o,visible])=>o.visible=visible);crewPoseRestore.forEach(({actor,position,rotation,visible})=>{actor.position.copy(position);actor.rotation.y=rotation;actor.visible=visible;});interiorActive=false;interiorKind='lab';controls.minDistance=5;controls.maxDistance=85;controls.minPolarAngle=0;controls.maxPolarAngle=Math.PI*.47;$('#mission-panel').classList.remove('interior');$('#exit-lab').textContent='Exit lab';$('#exit-lab').hidden=true;$('#station-nav').hidden=false;$('#hint').textContent='Drag to look around · Scroll / pinch to zoom · Click equipment to learn about it';controls.target.set(0,1,0);camera.position.set(30,23,34);controls.update();}
function enterFarm(){if(!surface||!farmInterior||interiorActive)return;if(activeCrew!==2){setFeedback('The greenhouse is a Scientist station. Switch to Player 2 · Scientist to enter.',false);return;}setViewMode(false);if(driving&&rover){const pilot=crewActor();if(pilot){pilot.position.set(rover.position.x+2,height(rover.position.x+2,rover.position.z+1),rover.position.z+1);pilot.visible=true;}driving=false;}heading=heading2=velocity=velocity2=0;interiorRestore=root.children.map(o=>[o,o.visible]);crewPoseRestore=[astronaut,astronaut2].filter(Boolean).map(a=>({actor:a,position:a.position.clone(),rotation:a.rotation.y,visible:a.visible}));interiorRestore.forEach(([o])=>o.visible=false);farmInterior.visible=true;if(astronaut)astronaut.visible=false;if(astronaut2){astronaut2.visible=true;astronaut2.position.set(0,0,2.72);astronaut2.rotation.y=0;}interiorKind='farm';interiorActive=true;$('#station-nav').hidden=true;$('#inspect').hidden=true;$('#mission-panel').classList.add('interior');$('#exit-lab').textContent='Exit greenhouse';$('#exit-lab').hidden=false;$('#hint').textContent='GREENHOUSE · Walk freely with arrow keys · Toggle first-person below · Click the irrigation, grow lights or crop monitor';controls.minDistance=1.3;controls.maxDistance=2.9;controls.minPolarAngle=.12;controls.maxPolarAngle=1.4;camera.position.set(0,2.1,2.65);controls.target.set(0,1.15,0);controls.update();}function focusStation(name){if(!surface)return;if(name==='garden'){enterFarm();return;}const obj=objects[name];if(!obj)return;if(name==='lab'){enterLab();return;}const p=obj.position;controls.target.set(p.x,p.y+1.2,p.z);camera.position.set(p.x+10,p.y+8,p.z+12);controls.update();const note=stationNote(name,level);if(note){$('#inspect-title').textContent=note[0];$('#inspect-text').textContent=note[1];$('#inspect').hidden=false;}}
function toggleVehicle(){if(onlineRole===2&&!driving){setFeedback("Player 1 is assigned to drive. As Scientist, move to the marked problem and handle the field task.");return;}const astronaut=crewActor();if(step!==3||solved||!astronaut||!rover)return;if(driving){const h=activeCrew===1?heading:heading2;astronaut.position.set(rover.position.x+2,height(rover.position.x+2,rover.position.z+1),rover.position.z+1);astronaut.rotation.y=h+Math.PI;astronaut.visible=true;driving=false;setFeedback(`Player ${activeCrew} stepped out of the rover. Walk to the green beacon or board again.`);}else if(astronaut.position.distanceTo(rover.position)<=6){astronaut.visible=false;driving=true;velocity=0;setFeedback(`Player ${activeCrew} is driving the rover. The other crew member can use their own movement keys.`);}else{setFeedback(`Player ${activeCrew}: walk close to the rover before boarding.`);return;}if(firstPerson){const ownModel=activeCrew===1?astronautModel:astronaut2Model;if(ownModel)ownModel.visible=driving;updateFirstPersonCamera();}$('#vehicle-mode').textContent=driving?`Player ${activeCrew} · Exit rover`:`Player ${activeCrew} · Board rover`;$('#vehicle-mode').disabled=false;$('#mobile-vehicle').textContent=driving?'Exit rover':'Board rover';$('#hint').textContent=driving?`Player ${activeCrew} driving · W/A/S/D or arrows · E to exit`:`Player ${activeCrew} on foot · ${activeCrew===1?'W/A/S/D':'arrow keys'} · E to board nearby`;}function updateTelemetry(){$('#battery').textContent=Math.round(battery)+' units';$('#air').textContent=Math.round(air)+' units';$('#shield').textContent=Math.round(shield)+' units';$('#power-meter').style.width=Math.round(battery)+'%';$('#air-meter').style.width=Math.round(air)+'%';$('#shield-meter').style.width=Math.round(shield)+'%';$('#signal').textContent=linked?(level==='beginner'?'SENT':'MESSAGE SENT'):(level==='beginner'?'NOT SENT':'OFFLINE');$('#sample').textContent=sample?sampleQuality:'—';$('#delay').textContent=linked?(world==='Moon'?'about 1.3 seconds':level==='beginner'?'3–22 minutes':'3–22 min one way'):'—';}
