 if(step===3){engineer.prompt='Drive the rover to the green beacon using W/A/S/D.';engineer.choices=[{label:'Engineer is ready to drive',power:0,air:0,food:0,note:'Player 1 has rover control.'}];scientist.title='PLAYER 2 · NAVIGATOR';scientist.prompt='Choose a route while the Engineer drives.';scientist.choices=[{label:'Mark a stable route and relay ridge',power:-1,air:1,food:0,note:'Route and relay margin checked.'},{label:'Take the shortest rough cut',power:-5,air:-2,food:0,note:'The route saves time but costs rover power and safety margin.'}];}
