 if(step===6){engineer.prompt='Set the relay to a low-power priority message.';engineer.choices=[{label:'Send a short priority packet',power:3,air:0,food:0,note:'The relay sends the essential status using less reserve.'},{label:'Stream every raw instrument file',power:-6,air:0,food:0,note:'More data is queued, using extra power.'}];scientist.title='PLAYER 2 · SCIENCE REPORTER';scientist.prompt='Choose what Earth needs to know first.';scientist.choices=[{label:'Send the measured clue and its uncertainty',power:-1,air:0,food:0,note:'The report includes evidence and its limits.'},{label:'Call the clue a confirmed resource',power:-4,air:0,food:0,note:'The unsupported claim triggers a repeat check and extra power use.'}];}
 if(step===7){engineer.prompt='Repair the solar array safely.';engineer.choices=[{label:'Isolate, inspect, repair, then verify output',power:7,air:0,food:0,note:'Fault isolated and output checked after repair.'},{label:'Bridge the damaged circuit while live',power:-8,air:-2,food:0,note:'Unsafe bypass drains reserve and leaves the fault uncertain.'}];scientist.prompt='Record the before-and-after power readings.';scientist.choices=[{label:'Compare baseline and repaired output',power:4,air:0,food:0,note:'Before-and-after readings confirm the repair.'},{label:'Record only the final meter value',power:-3,air:0,food:0,note:'Without a baseline, the team may repeat the check and waste power.'}];}
