function syncOnlineCrew(dt){const network=window.OutpostMultiplayer;if(!network?.connected?.()||!onlineRole)return;if(remoteCrewState&&remoteCrewState.role!==onlineRole&&surface&&remoteCrewState.world===world){const remoteActor=remoteCrewState.vehicle?rover:(remoteCrewState.role===1?astronaut:astronaut2),position=remoteCrewState.position;if(remoteActor&&position?.length===3){remoteActor.position.lerp(new THREE.Vector3(position[0],position[1],position[2]),Math.min(1,dt*10));remoteActor.rotation.y=Number(remoteCrewState.rotation)||0;if(!remoteCrewState.vehicle)remoteActor.visible=true;}}if(!surface)return;onlineSyncElapsed+=dt;if(onlineSyncElapsed<.12)return;onlineSyncElapsed=0;const actor=driving?rover:crewActor();if(!actor)return;network.sendState({role:onlineRole,world,region,step,position:actor.position.toArray(),rotation:actor.rotation.y,vehicle:driving,driveReached});}
